// GetCsrfToken operation middleware
func (siw *ServerInterfaceWrapper) GetCsrfToken(c *gin.Context) {

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.GetCsrfToken(c)
}

